-- PRASYARAT abt-saksi-rapi-3nov (BACA SAJA). Satu baris A|B|C:
--  A = isian_rtf_ket_saksi = versi titik-koma-30okt (md5 9ba910f2eb7ada8bd1807b08735af6db) (1 sebelum, 0 sesudah)
--  B = isian_rtf_tahu_lengkap dan isian_rtf_objek_tanya ada (0 sebelum, 2 sesudah)
--  C = isian_rtf_ket_saksi = versi paket ini (md5 69821f39aa74126aebe6a7caa935df47) (0 sebelum, 1 sesudah)
-- Pasang bila 1|0|0; pasang ulang bila 0|2|1; selain itu berhenti tanpa mengubah apa pun.
SELECT CONCAT_WS('|', (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name='isian_rtf_ket_saksi' AND MD5(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(routine_definition, CONCAT(DATABASE(), '.abt_'), 'aps_badilag.abt_'), CHAR(92), ''), ' ', ''), CHAR(9), ''), CHAR(13), ''), CHAR(10), '')) = '9ba910f2eb7ada8bd1807b08735af6db'), (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name='isian_rtf_tahu_lengkap') + (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name='isian_rtf_objek_tanya'), (SELECT COUNT(*) FROM information_schema.routines WHERE routine_schema=DATABASE() AND routine_type='FUNCTION' AND routine_name='isian_rtf_ket_saksi' AND MD5(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(routine_definition, CONCAT(DATABASE(), '.abt_'), 'aps_badilag.abt_'), CHAR(92), ''), ' ', ''), CHAR(9), ''), CHAR(13), ''), CHAR(10), '')) = '69821f39aa74126aebe6a7caa935df47')) AS prasyarat;
